// Builds a ~500 MB synthetic .ipa for the e2e performance budget (brief §6.5: "a 500 MB
// synthetic IPA analysed in under 10 s on a CI runner"). Written to fixtures/generated/, which
// .gitignore excludes — regenerated by the test itself, never committed. Run directly with
// `npx tsx fixtures/generators/large-ipa.ts`, or import `buildLargeIpa`/`largeIpaPath`.
import { mkdirSync, writeFileSync, existsSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { buildThinMachO } from './machO.ts';
import { encodeXmlPlist } from './plist.ts';
import { buildZip } from './zip.ts';

const repoRoot = join(dirname(fileURLToPath(import.meta.url)), '..', '..');
const generatedDir = join(repoRoot, 'fixtures/generated');

export const largeIpaPath = join(generatedDir, 'large.ipa');

const PADDING_BYTES = 500 * 1024 * 1024;

async function buildLargeIpa(): Promise<Uint8Array> {
  const infoPlist = encodeXmlPlist({
    CFBundleIdentifier: 'com.example.largeapp',
    CFBundleShortVersionString: '1.0.0',
    CFBundleVersion: '1',
    MinimumOSVersion: '15.0',
    CFBundleExecutable: 'LargeApp',
    DTXcode: '2600',
    DTSDKName: 'iphoneos26.0',
    DTPlatformVersion: '26.0',
  });

  return buildZip([
    { name: 'Payload/LargeApp.app/Info.plist', data: infoPlist },
    { name: 'Payload/LargeApp.app/LargeApp', data: buildThinMachO({}) },
    // A big same-named resource the analyzer never needs to read — only the zip's central
    // directory is read to find it, exercising the "never read a whole archive" architecture.
    {
      name: 'Payload/LargeApp.app/large-resource.dat',
      data: new Uint8Array(PADDING_BYTES),
      stored: true,
    },
  ]);
}

/** Generates fixtures/generated/large.ipa if it isn't already there. Idempotent and safe to call
 * from a test's setup — regenerating ~500 MB on every run would make the test itself slow. */
export async function ensureLargeIpa(): Promise<string> {
  if (!existsSync(largeIpaPath)) {
    mkdirSync(generatedDir, { recursive: true });
    writeFileSync(largeIpaPath, await buildLargeIpa());
  }
  return largeIpaPath;
}

if (import.meta.url === `file://${process.argv[1] ?? ''}`) {
  await ensureLargeIpa();
  console.log(`Wrote ${largeIpaPath}`);
}
